                out[#out + 1] = { pos = F.snap(hit.Position), stand = hit.Position }
            elseif kind == "ceil" then
                local up = Workspace:Raycast(hit.Position + Vector3.new(0, 1, 0), Vector3.new(0, part.Size.Y + 4, 0), F.rp)
                if up and up.Normal.Y <= -0.7 then out[#out + 1] = { pos = F.snap(up.Position), nrm = up.Normal, stand = hit.Position } end
            else
                local o = hit.Position + Vector3.new(0, 4, 0)
                for _, dv in ipairs({ part.CFrame.LookVector, -part.CFrame.LookVector, part.CFrame.RightVector, -part.CFrame.RightVector }) do
                    local wh = Workspace:Raycast(o, Vector3.new(dv.X, 0, dv.Z).Unit * 12, F.rp)
                    if wh and math.abs(wh.Normal.Y) <= (D.FC.WallMountMaxNormalY or 0.3) and not (pf and wh.Instance:IsDescendantOf(pf)) then
                        out[#out + 1] = { pos = F.snap(wh.Position), nrm = wh.Normal, stand = hit.Position }
                        break
                    end
                end
            end
        end
    end
    return out
end
F.sizeCache = {}
function F.size(id)
    if F.sizeCache[id] then return F.sizeCache[id] end
    local a = ReplicatedStorage:FindFirstChild("Assets")
    local fold = a and a:FindFirstChild(D.FC.AssetsFolderName or "Furniture")
    local m = fold and fold:FindFirstChild(id)
    local sz = Vector3.new(4, 4, 4)
    if m and m:IsA("Model") then local ok, e = pcall(function() return m:GetExtentsSize() end) if ok and e then sz = e end
    elseif m and m:IsA("BasePart") then sz = m.Size end
    F.sizeCache[id] = sz
    return sz
end
F.op = OverlapParams.new()
F.op.FilterType = Enum.RaycastFilterType.Exclude
function F.free(id, sp, yaw, kind)
    if kind ~= "floor" then return true end
    local sz = F.size(id) * 0.9
    local cf = CFrame.new(Vector3.new(sp.pos.X, (sp.stand or sp.pos).Y, sp.pos.Z) + Vector3.new(0, sz.Y / 2 + 0.2, 0)) * CFrame.Angles(0, math.rad(yaw), 0)
    F.op.FilterDescendantsInstances = F.excludes(false)
    local pf = Workspace:FindFirstChild(D.FC.PlacedFolderName or "PlacedFurniture")
    for _, p in ipairs(Workspace:GetPartBoundsInBox(cf, Vector3.new(sz.X, math.max(sz.Y - 0.5, 0.2), sz.Z), F.op)) do
        if p.CanCollide or (pf and p:IsDescendantOf(pf)) then return false end
    end
    return true
end
function F.roomCats()
    local rooms = F.rooms()
    local pf = Workspace:FindFirstChild(D.FC.PlacedFolderName or "PlacedFurniture")
    for _, r in ipairs(rooms) do r.has = {} end
    for _, m in ipairs(pf and pf:GetChildren() or {}) do
        if m:GetAttribute(D.FC.OwnerAttribute or "OwnerUserId") == lp.UserId then
            local it = F.item(m:GetAttribute(D.FC.IdAttribute or "FurnitureId"))
            local ok, pv = pcall(function() return m:GetPivot().Position end)
            if it and it.category and ok then
                for _, r in ipairs(rooms) do
                    local l = r.part.CFrame:PointToObjectSpace(pv)
                    if math.abs(l.X) <= r.part.Size.X / 2 and math.abs(l.Y) <= r.part.Size.Y / 2 + 1 and math.abs(l.Z) <= r.part.Size.Z / 2 then r.has[it.category] = true break end
                end
            end
        end
    end
    return rooms
end
function F.place(tool)
    local id = tool:GetAttribute(D.FC.IdAttribute or "FurnitureId")
    local uuid = tool:GetAttribute(D.FC.UuidAttribute or "FurnitureUuid")
    local it = F.item(id)
    local cat = it and it.category
    local kind = F.kind(id)
    local house0 = M.prof().House
    local rooms = F.roomCats()
    local function score(r)
        local wants = false
        for _, c in ipairs(r.wants) do if c == cat then wants = true end end
        if wants and not r.has[cat] then return 3 end
        if wants then return 2 end
        return 1
    end
    table.sort(rooms, function(a, b) return score(a) > score(b) end)
    local cands = {}
    for _, r in ipairs(rooms) do cands[#cands + 1] = r.part end
    local sc = M.scripted()
    for _, c in ipairs(sc and sc:GetChildren() or {}) do if c.Name == (D.PC.HouseBoundsName or "HouseBounds") and c:IsA("BasePart") then cands[#cands + 1] = c end end
    local tries = 0
    local loose = {}
    for pass = 1, 2 do
    for _, part in ipairs(pass == 1 and cands or {}) do
        for _, sp in ipairs(F.spotsIn(part, kind)) do
            if not RUNNING or F.pause() then return false, "paused" end
            if M.prof().House ~= house0 then return false, "moved" end
            local yaw = math.random(0, 3) * 90
            local okFree = F.free(id, sp, yaw, kind)
            if not okFree then yaw = (yaw + 90) % 360 okFree = F.free(id, sp, yaw, kind) end
            if not okFree and #loose < 10 then loose[#loose + 1] = { sp = sp, yaw = yaw } end
            if okFree then
                tries += 1
                local r = M.root()
                if r and (r.Position - sp.pos).Magnitude > (D.FC.MaxPlaceDistance or 25) - 6 then M.tp(sp.stand + Vector3.new(0, 3, 0)) task.wait(0.15) end
                local ok, why = M.call("FurniturePlace", uuid, sp.pos, yaw, sp.nrm)
                if ok == true then S.placed = (S.placed or 0) + 1 return true end
                F.lastWhy = tostring(why)
                local w = F.lastWhy:lower()
                if w:find("placed all") or w:find("slot") then return false, "full" end
                if tries >= 12 then break end
            end
        end
        if tries >= 24 then break end
    end
    if pass == 2 and tries == 0 then
        for _, l in ipairs(loose) do
            if not RUNNING or F.pause() then return false, "paused" end
            tries += 1
            local r = M.root()
            if r and (r.Position - l.sp.pos).Magnitude > (D.FC.MaxPlaceDistance or 25) - 6 then M.tp(l.sp.stand + Vector3.new(0, 3, 0)) task.wait(0.15) end
            local ok, why = M.call("FurniturePlace", uuid, l.sp.pos, l.yaw, l.sp.nrm)
            if ok == true then S.placed = (S.placed or 0) + 1 return true end
            F.lastWhy = tostring(why)
        end
    end
    if tries > 0 then break end
    end
    LOG("place failed", id, kind, F.lastWhy, "tries", tries)
    if tries == 0 then
        F.zero = F.zero or {}
        F.zero[uuid] = (F.zero[uuid] or 0) + 1
        if F.zero[uuid] >= 3 then F.skip[uuid] = true F.zero[uuid] = 0 task.delay(180, function() F.skip[uuid] = nil end) end
    end
    if tries > 0 then
        F.fails = F.fails or {}
        F.fails[uuid] = (F.fails[uuid] or 0) + 1
        if F.fails[uuid] >= 2 then if not F.trash(tool) then F.skip[uuid] = true end end
    end
    return false
end
function F.trashCan()
    local plot = M.plot()
    for _, d in ipairs(plot and plot:GetDescendants() or {}) do
        if d:IsA("Model") and d:GetAttribute(D.IC.ActionAttribute or "InteractAction") == "Trash" then return d end
    end
end
function F.trash(tool)
    local can = F.trashCan()
    local h = M.hum()
    if not can or not h or not tool.Parent then return false end
    pcall(function() h:EquipTool(tool) end)
    task.wait(0.3)
    M.tp(can:GetPivot().Position + Vector3.new(0, 3, 3))
    task.wait(0.25)
    local r = M.call("Interact", "Trash", can)
    LOG("trashed", tool:GetAttribute(D.FC.IdAttribute or "FurnitureId"), tostring(r))
    pcall(function() h:UnequipTools() end)
    return r == true
end
function F.pickupDropped()
    local df = Workspace:FindFirstChild(D.FC.DroppedFolderName or "DroppedFurniture")
    for _, m in ipairs(df and df:GetChildren() or {}) do
        if m:GetAttribute(D.FC.OwnerAttribute or "OwnerUserId") == lp.UserId and not (F.bad[m] and F.bad[m] > os.clock()) and #F.held() < F.carryCap() then
            local ok, pv = pcall(function() return m:GetPivot().Position end)
            if ok then
                M.tp(pv + Vector3.new(0, 3, 2))
                task.wait(0.2)
                local r = M.call("Interact", "PickupDropped", m)
                if r ~= true then F.bad[m] = os.clock() + 30 end
                LOG("picked up dropped", tostring(r))
            end
        end
    end
end
function F.nightSoon()
    if M.danger() then return true end
    local start = Workspace:GetAttribute(D.DN.CycleStartAttribute or "DayNightCycleStart")
    local order, dur = D.DN.Order, D.DN.Durations
    if not start or not order or not dur then return false end
    local total = 0
    for _, ph in ipairs(order) do total += dur[ph] or 0 end
    if total <= 0 then return false end
    local t = (Workspace:GetServerTimeNow() - start) % total
    local acc = 0
    for _, ph in ipairs(order) do
        if (D.DN.BeastHunts or { Night = true })[ph] then return acc - t > 0 and acc - t < 15 end
        acc += dur[ph] or 0
    end
    return false
end
function F.myPlaced()
    local pf = Workspace:FindFirstChild(D.FC.PlacedFolderName or "PlacedFurniture")
    local out = {}
    local h = M.house()
    for _, m in ipairs(pf and pf:GetChildren() or {}) do
        if m:GetAttribute(D.FC.OwnerAttribute or "OwnerUserId") == lp.UserId then
            local id = m:GetAttribute(D.FC.IdAttribute or "FurnitureId")
            local it = F.item(id)
            local ok, pv = pcall(function() return m:GetPivot().Position end)
            if it and ok and M.inside(pv) then out[#out + 1] = { m = m, id = id, c = it.comfort or 0, cat = it.category, pos = pv } end
        end
    end
    table.sort(out, function(a, b) return a.c < b.c end)
    return out
end
function F.foot(id) local z = F.size(id) return z.X * z.Z end
function F.placeAt(tool, pos, yaw)
    local uuid = tool:GetAttribute(D.FC.UuidAttribute or "FurnitureUuid")
    F.rp.FilterDescendantsInstances = F.excludes(true)
    local hit = Workspace:Raycast(pos + Vector3.new(0, 3, 0), Vector3.new(0, -10, 0), F.rp)
    local fpos = hit and hit.Position or pos
    local r = M.root()
    if r and (r.Position - fpos).Magnitude > 15 then M.tp(fpos + Vector3.new(0, 3, 2)) task.wait(0.15) end
    for _, yw in ipairs({ yaw, (yaw + 90) % 360, (yaw + 180) % 360, (yaw + 270) % 360 }) do
        local ok = M.call("FurniturePlace", uuid, F.snap(fpos), yw, nil)
        if ok == true then S.placed = (S.placed or 0) + 1 return true end
    end
    return false
end
function F.upgrade()
    if not on("f_upgrade") or F.nightSoon() or (F.upNext or 0) > os.clock() then S.task = __T["House full"] return false end
    local mine = F.myPlaced()
    if #mine == 0 then return false end
    local held = {}
    for _, t in ipairs(F.held()) do
        local id = t:GetAttribute(D.FC.IdAttribute or "FurnitureId")
        local it = F.item(id)
        if it and F.kind(id) == "floor" then held[#held + 1] = { t = t, id = id, c = it.comfort or 0 } end
    end
    table.sort(held, function(x, y) return x.c > y.c end)
    for _, worst in ipairs(mine) do
        if F.kind(worst.id) == "floor" and not (F.bad[worst.m] and F.bad[worst.m] > os.clock()) then
            local wf = F.foot(worst.id) * 1.15
            local pick
            for _, h in ipairs(held) do if h.c - worst.c >= 3 and F.foot(h.id) <= wf then pick = h break end end
            local stockPick
            if not pick and #F.held() < F.carryCap() then
                for _, m in ipairs(F.stock()) do
                    local id = m:GetAttribute(D.SM.IdAttribute or "FurnitureId")
                    local it = id and F.item(id)
                    if it and F.kind(id) == "floor" and m:GetAttribute(D.SM.SpotAttribute or "SpawnSpot") ~= nil and not (F.bad[m] and F.bad[m] > os.clock())
                        and (it.comfort or 0) - worst.c >= 3 and F.foot(id) <= wf and (not stockPick or (it.comfort or 0) > stockPick.c) then
                        stockPick = { m = m, id = id, c = it.comfort or 0 }
                    end
                end
            end
            if pick or stockPick then
                S.busy = true
                S.task = __T["Upgrading furniture"]
                if stockPick then
                    if not F.take(stockPick) then S.busy = false return true end
                    for _, t in ipairs(F.held()) do if t:GetAttribute(D.FC.IdAttribute or "FurnitureId") == stockPick.id then pick = { t = t, id = stockPick.id, c = stockPick.c } end end
                end
                if not pick then S.busy = false return true end
                local yaw = 0
                pcall(function() local _, y = worst.m:GetPivot():ToOrientation() yaw = math.floor(math.deg(y) / 90 + 0.5) * 90 % 360 end)
                if #F.held() >= F.carryCap() then
                    local lo, lc
                    for _, t in ipairs(F.held()) do
                        if t ~= pick.t then local it = F.item(t:GetAttribute(D.FC.IdAttribute or "FurnitureId")) local c = it and it.comfort or 0 if not lc or c < lc then lo, lc = t, c end end
                    end
                    if lo then F.trash(lo) task.wait(0.2) end
                end
                M.tp(worst.pos + Vector3.new(0, 3, 3))
                task.wait(0.25)
                local r = M.call("Interact", "Pickup", worst.m)
                LOG("upgrade", worst.id, worst.c, "->", pick.id, pick.c, "pickup", tostring(r))
                if r ~= true then F.bad[worst.m] = os.clock() + 120 S.busy = false return true end
                task.wait(0.2)
                local ok = F.placeAt(pick.t, worst.pos, yaw) or F.place(pick.t)
                local oldT
                for _, t in ipairs(F.held()) do if t:GetAttribute(D.FC.IdAttribute or "FurnitureId") == worst.id then oldT = t end end
                if ok then
                    S.upgrades = (S.upgrades or 0) + 1
                    if oldT then F.trash(oldT) end
                elseif oldT then
                    F.placeAt(oldT, worst.pos, yaw)
                end
                if not F.pause() then M.goInside() end
                M.prof(true)
                S.busy = false
                return true
            end
        end
    end
    S.task = __T["House full"]
    F.upNext = os.clock() + 20
    return false
end
function F.furnish()
    if F.nightSoon() and not on("f_night") then return false end
    if F.roomyAt and F.roomyAt.house == M.prof().House and os.clock() < F.roomyAt.t then S.task = __T["House full"] return false end
    if F.placedCount() >= F.slots() then
        local held = 0
        for _, t in ipairs(F.held()) do if not F.skip[t:GetAttribute(D.FC.UuidAttribute or "FurnitureUuid")] then held += 1 end end
        S.task = __T["House full"]
        return false
    end
    local house0 = M.prof().House
    S.busy = true
    F.pickupDropped()
    local held = {}
    for _, t in ipairs(F.held()) do if not F.skip[t:GetAttribute(D.FC.UuidAttribute or "FurnitureUuid")] then held[#held + 1] = t end end
    local room = math.min(F.carryCap() - #F.held(), F.slots() - F.placedCount() - #held)
    if room > 0 then
        local picks = F.pickItems(room)
        if #picks > 0 then
            S.task = __T["Shopping"]
            for _, e in ipairs(picks) do
                if not RUNNING or F.pause() or (F.nightSoon() and not on("f_night")) then break end
                F.take(e)
            end
        elseif #held == 0 then S.task = __T["Supermarket empty"] S.busy = false return false end
    end
    if not RUNNING or F.pause() then S.busy = false return false end
    held = {}
    for _, t in ipairs(F.held()) do if not F.skip[t:GetAttribute(D.FC.UuidAttribute or "FurnitureUuid")] then held[#held + 1] = t end end
    if #held == 0 then S.busy = false return false end
    S.task = __T["Furnishing"]
    M.goInside()
    task.wait(0.3)
    for _, t in ipairs(held) do
        if not RUNNING or F.pause() or M.prof().House ~= house0 then break end
        local ok, why = F.place(t)
        if ok then F.failRun = 0 elseif why ~= "moved" and why ~= "paused" then F.failRun = (F.failRun or 0) + 1 end
        if (F.failRun or 0) >= 3 then F.roomyAt = { house = house0, t = os.clock() + 300 } F.failRun = 0 LOG("no room left, waiting for a bigger house") break end
        if why == "full" or why == "moved" or why == "paused" then break end
    end
    if not F.pause() then M.goInside() end
    M.prof(true)
    S.busy = false
    return true
end
function F.capacity()
    local p = M.prof()
    local h = M.houseDef(p.House)
    local cap = (h and h.rooms or 1) * (D.SC.CapPerRoom or 1)
    if (p.Shop or {}).SurvivorCapacity then cap += D.SH.SurvivorCapacityBonus or 0 end
    return cap
end
function F.housed()
    local n = 0
    for _ in pairs(M.prof().Survivors or {}) do n += 1 end
    return n
end
function F.rRank(r) for i, v in ipairs(D.SC.RarityOrder or {}) do if v == r then return i end end return 0 end
function F.knockers()
    local out = {}
    local kf = D.KC.KnockingForAttribute or "KnockingFor"
    local oa = D.SC.OwnerAttribute or "OwnerUserId"
    for _, s in ipairs(CS:GetTagged(D.SC.Tag or "Survivor")) do
        if s:GetAttribute(kf) == lp.UserId and s:GetAttribute(oa) == nil and not s:GetAttribute(D.SC.MovingInAttribute or "MovingIn") and s:GetAttribute(D.SC.StateAttribute or "State") ~= "Dead" and not (F.bad[s] and F.bad[s] > os.clock()) then out[#out + 1] = s end
    end
    table.sort(out, function(a, b) return F.rRank(a:GetAttribute(D.SC.RarityAttribute or "Rarity")) > F.rRank(b:GetAttribute(D.SC.RarityAttribute or "Rarity")) end)
    return out
end
function F.beastNear(pos, r)
    local b = Workspace:FindFirstChild(D.BeastName or "Beast")
    if not b then return false end
    local ok, pv = pcall(function() return b:GetPivot().Position end)
    return ok and (pv - pos).Magnitude < r
end
function F.guests()
    local ks = F.knockers()
    if #ks == 0 then return false end
    if F.housed() >= F.capacity() then M.prof(true) if F.housed() >= F.capacity() then S.task = __T["House full of guests"] return false end end
    local s = ks[1]
    local sp = s:FindFirstChild("HumanoidRootPart") or s.PrimaryPart
    if not sp then return false end
    S.busy = true
    S.task = __T["Letting a guest in"]
    local r0 = M.root()
    local back = r0 and r0.CFrame
    local moved = false
    if r0 and (r0.Position - sp.Position).Magnitude > 12 then
        if M.danger() and F.beastNear(sp.Position, 60) then F.bad[s] = os.clock() + 5 S.busy = false return false end
        M.tp(sp.Position + (sp.CFrame.LookVector * 4) + Vector3.new(0, 1, 0))
        moved = true
        task.wait(0.25)
    end
    local r = M.call("Interact", "Invite", s)
    LOG("invite", s:GetAttribute(D.SC.NameAttribute or "SurvivorName"), s:GetAttribute(D.SC.RarityAttribute or "Rarity"), tostring(r))
    if r == true then S.guests = (S.guests or 0) + 1 else F.bad[s] = os.clock() + 20 end
    M.prof(true)
    if moved then if M.danger() then M.goInside() elseif back then M.tp(back) end end
    S.busy = false
    return true
end
function F.safety()
