track(RunService.Heartbeat:Connect(function(dt)
    if not on("p_fly") or S.busy then return end
    local r, h = M.root(), M.hum()
    local cam = Workspace.CurrentCamera
    if not r or not h or not cam then return end
    local mv = h.MoveDirection
    local up = 0
    if UIS:IsKeyDown(Enum.KeyCode.Space) then up = 1 elseif UIS:IsKeyDown(Enum.KeyCode.LeftControl) then up = -1 end
    local look = cam.CFrame.LookVector
    local dir = mv
    if mv.Magnitude > 0 then
        local flat = Vector3.new(look.X, 0, look.Z)
        if flat.Magnitude > 0 and mv:Dot(flat.Unit) > 0.5 then dir = mv + Vector3.new(0, look.Y, 0) end
    end
    dir = dir + Vector3.new(0, up, 0)
    local spd = tonumber(val("p_fly_v", 50)) or 50
    r.AssemblyLinearVelocity = Vector3.zero
    if dir.Magnitude > 0 then r.CFrame = r.CFrame + dir.Unit * spd * dt end
end))
