    local groups = {
        { __T["Farm"], { __T["+ Instant furnish"], __T["+ Pick what to take"], __T["+ Grab furniture instantly"], __T["+ Best comfort first"], __T["+ Fills every room set"], __T["+ Auto accept guests"], __T["+ Beast safe at night"] } },
        { __T["Upgrades"], { __T["+ Auto buy best house"], __T["+ Auto claim badges"], __T["+ Auto claim reward"] } },
        { "Player", { __T["+ Third person"], __T["+ Fly + noclip"], __T["+ Speed + inf jump"], __T["+ Teleport to players"], __T["+ Beast + guest ESP"], __T["+ Anti AFK"] } },
        { __T["Other"], { __T["+ Streamer mode"] } },
    }
    for _, g in ipairs(groups) do
        CG:AddLabel('<b>' .. g[1] .. '</b>', true)
        for _, l in ipairs(g[2]) do CG:AddLabel(l, true) end
    end
end)
